package com.esn.smp.gameplay;
import com.esn.smp.data.ESNDataStore;import org.bukkit.*;import org.bukkit.attribute.Attribute;import org.bukkit.command.*;import org.bukkit.entity.*;import org.bukkit.event.*;import org.bukkit.event.entity.*;import org.bukkit.event.player.*;import org.bukkit.inventory.*;import org.bukkit.inventory.meta.ItemMeta;import org.bukkit.persistence.*;import org.bukkit.plugin.java.JavaPlugin;import org.bukkit.potion.*;import java.util.*;import java.util.concurrent.ThreadLocalRandom;
public final class Fun20Core implements Listener,CommandExecutor{
 private final JavaPlugin p;private final ESNDataStore eco;private final NamespacedKey artifact,rune,ascension;private String chaos="CALM";private long chaosEnd=0;private final Map<UUID,Long> abilityCd=new HashMap<>();private long communityKills=0;private final Set<UUID> trials=new HashSet<>();
 public Fun20Core(JavaPlugin p,ESNDataStore e){this.p=p;eco=e;artifact=new NamespacedKey(p,"artifact");rune=new NamespacedKey(p,"rune");ascension=new NamespacedKey(p,"ascension");Bukkit.getScheduler().runTaskTimer(p,this::rollChaos,24000L,24000L);Bukkit.getScheduler().runTaskTimer(p,this::meteor,72000L,72000L);}
 public boolean onCommand(CommandSender s,Command c,String l,String[] a){if(!(s instanceof Player x))return true;switch(c.getName()){case"chaos"->x.sendMessage(ChatColor.LIGHT_PURPLE+"Chaos: "+chaos+(active()?ChatColor.GRAY+" active":""));case"artifacts"->x.sendMessage(ChatColor.GOLD+"Artifacts: rare permanent trophies drop from bosses. Hold one for its passive.");case"runes"->x.sendMessage(ChatColor.AQUA+"Runes drop from elites and can be combined with ESN progression rewards.");case"ascend"->ascend(x);case"community"->x.sendMessage(ChatColor.GREEN+"Community Hunt: "+communityKills+"/5000 hostile kills");case"supplydrop"->supply(x.getLocation());case"merchant"->merchant(x);case"endless"->endless(x);case"fishingevent"->x.sendMessage(ChatColor.AQUA+"Fishing Frenzy: custom treasure can be caught while the event is active.");case"runeforge"->socket(x);case"setbonus"->setBonus(x);}return true;}
 private boolean active(){return System.currentTimeMillis()<chaosEnd;}
 private void rollChaos(){if(Bukkit.getOnlinePlayers().isEmpty())return;String[] a={"LOW GRAVITY","MOB APOCALYPSE","FORTUNE HOUR","BOSS MANIA","KEY FRENZY","THUNDERDOME","TREASURE RUSH","NIGHTMARE","ETERNAL HOUR"};chaos=a[ThreadLocalRandom.current().nextInt(a.length)];chaosEnd=System.currentTimeMillis()+15*60_000L;Bukkit.broadcastMessage(ChatColor.LIGHT_PURPLE+"ESN CHAOS: "+chaos+ChatColor.GRAY+" — 15 minutes!");if(chaos.equals("TREASURE RUSH"))for(Player x:Bukkit.getOnlinePlayers())supply(x.getLocation());}
 private void meteor(){if(Bukkit.getOnlinePlayers().isEmpty())return;Player x=new ArrayList<>(Bukkit.getOnlinePlayers()).get(ThreadLocalRandom.current().nextInt(Bukkit.getOnlinePlayers().size()));Location l=x.getLocation().clone().add(ThreadLocalRandom.current().nextInt(-180,181),0,ThreadLocalRandom.current().nextInt(-180,181));l.setY(l.getWorld().getHighestBlockYAt(l)+1);l.getWorld().strikeLightningEffect(l);for(int i=0;i<6;i++){Zombie z=l.getWorld().spawn(l,Zombie.class);z.setCustomName(ChatColor.DARK_PURPLE+"Meteor Guardian");z.addScoreboardTag("esnElite");z.getAttribute(Attribute.MAX_HEALTH).setBaseValue(60);z.setHealth(60);}l.getWorld().dropItemNaturally(l,CustomItems.cosmicCore());Bukkit.broadcastMessage(ChatColor.LIGHT_PURPLE+"METEOR CRASH near X "+l.getBlockX()+" Z "+l.getBlockZ()+"! Guardians protect a Cosmic Core.");}
 private void supply(Location near){Location l=near.clone().add(ThreadLocalRandom.current().nextInt(-80,81),0,ThreadLocalRandom.current().nextInt(-80,81));l.setY(l.getWorld().getHighestBlockYAt(l)+1);l.getWorld().dropItemNaturally(l,LootDrops.key());l.getWorld().dropItemNaturally(l,ThreadLocalRandom.current().nextBoolean()?CustomItems.voidShard():CustomItems.titanFragment());Bukkit.broadcastMessage(ChatColor.GOLD+"Supply Drop landed near X "+l.getBlockX()+" Z "+l.getBlockZ());}
 @EventHandler public void spawn(CreatureSpawnEvent e){if(!(e.getEntity() instanceof Monster m)||ThreadLocalRandom.current().nextDouble()>.035)return;m.addScoreboardTag("esnElite");String[] mods={"Vampiric","Swift","Armored","Storm","Toxic","Infernal","Frozen","Void-Touched"};String mod=mods[ThreadLocalRandom.current().nextInt(mods.length)];m.setCustomName(ChatColor.RED+"Elite "+mod+" "+m.getType().name());if(m.getAttribute(Attribute.MAX_HEALTH)!=null){double hp=Math.min(200,m.getAttribute(Attribute.MAX_HEALTH).getBaseValue()*3);m.getAttribute(Attribute.MAX_HEALTH).setBaseValue(hp);m.setHealth(hp);}m.addPotionEffect(new PotionEffect(mod.equals("Swift")?PotionEffectType.SPEED:PotionEffectType.RESISTANCE,Integer.MAX_VALUE,1));}
 @EventHandler public void death(EntityDeathEvent e){Player x=e.getEntity().getKiller();if(x==null)return;if(e.getEntity() instanceof Monster)communityKills++;if(e.getEntity().getScoreboardTags().contains("esnElite")){if(ThreadLocalRandom.current().nextDouble()<.35)e.getDrops().add(rune());try{eco.deposit(x,250);}catch(Exception ignored){}}if(e.getEntity().getScoreboardTags().contains("esnWorldBoss")||e.getEntity().getScoreboardTags().contains("esnSwampBoss"))if(ThreadLocalRandom.current().nextDouble()<.12)e.getDrops().add(artifact());if(communityKills>0&&communityKills%5000==0){Bukkit.broadcastMessage(ChatColor.GREEN+"COMMUNITY GOAL COMPLETE! Every online player gets an ESN key.");for(Player q:Bukkit.getOnlinePlayers())q.getInventory().addItem(LootDrops.key());}}
 private ItemStack artifact(){ItemStack i=new ItemStack(Material.NETHER_STAR);ItemMeta m=i.getItemMeta();m.setDisplayName(ChatColor.GOLD+"Mythic Boss Artifact");m.setLore(List.of(ChatColor.LIGHT_PURPLE+"Rare boss trophy",ChatColor.GRAY+"Hold for Strength I"));m.getPersistentDataContainer().set(artifact,PersistentDataType.BYTE,(byte)1);i.setItemMeta(m);return i;}
 private ItemStack rune(){ItemStack i=new ItemStack(Material.PRISMARINE_CRYSTALS);ItemMeta m=i.getItemMeta();m.setDisplayName(ChatColor.AQUA+"Elite Rune");m.setLore(List.of(ChatColor.GRAY+"Dropped by Elite mobs",ChatColor.YELLOW+"Used in endgame progression"));m.getPersistentDataContainer().set(rune,PersistentDataType.BYTE,(byte)1);i.setItemMeta(m);return i;}
 @EventHandler public void hold(PlayerItemHeldEvent e){Bukkit.getScheduler().runTaskLater(p,()->{ItemStack i=e.getPlayer().getInventory().getItemInMainHand();if(i!=null&&i.hasItemMeta()&&i.getItemMeta().getPersistentDataContainer().has(artifact,PersistentDataType.BYTE))e.getPlayer().addPotionEffect(new PotionEffect(PotionEffectType.STRENGTH,240,0));},1);}
 @EventHandler public void use(PlayerInteractEvent e){Player x=e.getPlayer();ItemStack i=e.getItem();if(i==null||!i.hasItemMeta())return;String n=ChatColor.stripColor(i.getItemMeta().getDisplayName());if(!n.startsWith("Eternal "))return;if(abilityCd.getOrDefault(x.getUniqueId(),0L)>System.currentTimeMillis())return;abilityCd.put(x.getUniqueId(),System.currentTimeMillis()+30000);if(n.contains("Dominion")||n.contains("Ruin")){for(Entity z:x.getNearbyEntities(7,4,7))if(z instanceof Monster m)m.damage(18,x);x.getWorld().spawnParticle(Particle.SONIC_BOOM,x.getLocation().add(0,1,0),3);}else{x.addPotionEffect(new PotionEffect(PotionEffectType.SPEED,200,2));x.addPotionEffect(new PotionEffect(PotionEffectType.RESISTANCE,200,1));}x.sendActionBar(ChatColor.DARK_AQUA+"Eternal ability activated — 30s cooldown");}
 private void ascend(Player x){ItemStack i=x.getInventory().getItemInMainHand();if(i==null||!i.hasItemMeta()||!ChatColor.stripColor(i.getItemMeta().getDisplayName()).startsWith("Eternal ")){x.sendMessage(ChatColor.RED+"Hold Eternal equipment.");return;}int lv=i.getItemMeta().getPersistentDataContainer().getOrDefault(ascension,PersistentDataType.INTEGER,0);if(lv>=5){x.sendMessage(ChatColor.GOLD+"This item is Eternal V.");return;}if(!consumeRune(x,2+lv)){x.sendMessage(ChatColor.RED+"You need "+(2+lv)+" Elite Runes.");return;}ItemMeta m=i.getItemMeta();m.getPersistentDataContainer().set(ascension,PersistentDataType.INTEGER,lv+1);List<String> lore=m.hasLore()?new ArrayList<>(m.getLore()):new ArrayList<>();lore.add(ChatColor.GOLD+"Ascension: Eternal "+roman(lv+1));m.setLore(lore);i.setItemMeta(m);x.sendMessage(ChatColor.GOLD+"Ascended to Eternal "+roman(lv+1)+"!");}
 private boolean consumeRune(Player x,int n){int have=0;for(ItemStack i:x.getInventory().getContents())if(i!=null&&i.hasItemMeta()&&i.getItemMeta().getPersistentDataContainer().has(rune,PersistentDataType.BYTE))have+=i.getAmount();if(have<n)return false;for(int s=0;s<x.getInventory().getSize()&&n>0;s++){ItemStack i=x.getInventory().getItem(s);if(i==null||!i.hasItemMeta()||!i.getItemMeta().getPersistentDataContainer().has(rune,PersistentDataType.BYTE))continue;int q=Math.min(n,i.getAmount());i.setAmount(i.getAmount()-q);n-=q;if(i.getAmount()==0)x.getInventory().setItem(s,null);}return true;}
 private String roman(int n){return new String[]{"","I","II","III","IV","V"}[n];}
 private void merchant(Player x){Inventory v=Bukkit.createInventory(null,9,ChatColor.DARK_PURPLE+"Mystery Merchant");v.setItem(2,priced(LootDrops.key(),1500));v.setItem(4,priced(CustomItems.voidShard(),2500));v.setItem(6,priced(CustomItems.celestialCrystal(),5000));x.openInventory(v);} private ItemStack priced(ItemStack i,int price){ItemMeta m=i.getItemMeta();List<String> l=m.hasLore()?new ArrayList<>(m.getLore()):new ArrayList<>();l.add(ChatColor.GOLD+"Price: "+price+" Coins");m.setLore(l);i.setItemMeta(m);return i;}
 private void endless(Player x){if(!trials.add(x.getUniqueId())){x.sendMessage(ChatColor.RED+"You already have a trial running.");return;}x.sendMessage(ChatColor.RED+"ENDLESS TRIAL: 10 escalating waves, bosses on waves 5 and 10.");Location l=x.getLocation().clone();for(int wave=1;wave<=10;wave++){final int w=wave;Bukkit.getScheduler().runTaskLater(p,()->{if(!x.isOnline()){trials.remove(x.getUniqueId());return;}int count=4+w*2;for(int n=0;n<count;n++){Zombie z=l.getWorld().spawn(l.clone().add(ThreadLocalRandom.current().nextInt(-8,9),0,ThreadLocalRandom.current().nextInt(-8,9)),Zombie.class);z.setCustomName(ChatColor.RED+"Trial "+w);z.addScoreboardTag("esnTrial");if(w==5||w==10)z.addScoreboardTag("esnElite");}x.sendMessage(ChatColor.GOLD+"Trial wave "+w+"/10");if(w==10)Bukkit.getScheduler().runTaskLater(p,()->{trials.remove(x.getUniqueId());if(x.isOnline()){try{eco.deposit(x,5000);}catch(Exception ignored){}x.getInventory().addItem(LootDrops.key());x.sendMessage(ChatColor.GREEN+"Trial completed: 5,000 Coins + key!");}},300L);},wave*300L);}} private void socket(Player x){ItemStack gear=x.getInventory().getItemInMainHand();if(gear==null||gear.getType().isAir()){x.sendMessage(ChatColor.RED+"Hold gear in your main hand and keep an Elite Rune in your inventory.");return;}if(!consumeRune(x,1)){x.sendMessage(ChatColor.RED+"You need an Elite Rune.");return;}ItemMeta m=gear.getItemMeta();int lv=m.getPersistentDataContainer().getOrDefault(rune,PersistentDataType.INTEGER,0);if(lv>=3){x.getInventory().addItem(rune());x.sendMessage(ChatColor.RED+"That item already has 3 runes.");return;}m.getPersistentDataContainer().set(rune,PersistentDataType.INTEGER,lv+1);List<String> lore=m.hasLore()?new ArrayList<>(m.getLore()):new ArrayList<>();lore.add(ChatColor.AQUA+"Rune Socket "+(lv+1)+": Empowered");m.setLore(lore);gear.setItemMeta(m);x.sendMessage(ChatColor.AQUA+"Rune socketed. "+(lv+1)+"/3");} private void setBonus(Player x){int pieces=0;for(ItemStack i:x.getInventory().getArmorContents())if(i!=null&&i.hasItemMeta()&&ChatColor.stripColor(i.getItemMeta().getDisplayName()).startsWith("Eternal "))pieces++;x.sendMessage(ChatColor.DARK_AQUA+"Eternal Set: "+pieces+"/4 | 2pc Speed I | 3pc Strength I | 4pc Resistance I");}
 @EventHandler public void merchantClick(org.bukkit.event.inventory.InventoryClickEvent e){if(!e.getView().getTitle().equals(ChatColor.DARK_PURPLE+"Mystery Merchant"))return;e.setCancelled(true);if(!(e.getWhoClicked() instanceof Player x))return;int slot=e.getRawSlot(),price=slot==2?1500:slot==4?2500:slot==6?5000:0;if(price==0)return;ItemStack item=e.getInventory().getItem(slot);if(item==null)return;try{if(!eco.withdraw(x,price)){x.sendMessage(ChatColor.RED+"Not enough Coins.");return;}ItemStack reward=item.clone();ItemMeta m=reward.getItemMeta();if(m.hasLore()){List<String> l=new ArrayList<>(m.getLore());l.removeIf(z->ChatColor.stripColor(z).startsWith("Price:"));m.setLore(l);reward.setItemMeta(m);}Map<Integer,ItemStack> left=x.getInventory().addItem(reward);if(!left.isEmpty()){eco.deposit(x,price);x.sendMessage(ChatColor.RED+"Inventory full; refunded.");}else x.sendMessage(ChatColor.GREEN+"Merchant purchase complete.");}catch(Exception z){x.sendMessage(ChatColor.RED+"Purchase failed safely.");}}
 @EventHandler public void fish(PlayerFishEvent e){if(e.getState()!=PlayerFishEvent.State.CAUGHT_FISH)return;if(active()&&chaos.equals("FORTUNE HOUR")&&ThreadLocalRandom.current().nextDouble()<.25)e.getPlayer().getInventory().addItem(ThreadLocalRandom.current().nextBoolean()?rune():LootDrops.key());}
 @EventHandler public void tickSet(EntityDamageEvent e){if(!(e.getEntity() instanceof Player x))return;int pieces=0;for(ItemStack i:x.getInventory().getArmorContents())if(i!=null&&i.hasItemMeta()&&ChatColor.stripColor(i.getItemMeta().getDisplayName()).startsWith("Eternal "))pieces++;if(pieces>=4)e.setDamage(e.getDamage()*.85);if(pieces>=2)x.addPotionEffect(new PotionEffect(PotionEffectType.SPEED,100,0));if(pieces>=3)x.addPotionEffect(new PotionEffect(PotionEffectType.STRENGTH,100,0));}
}